/** 
 * Returns a <tt>Map</tt>, containing all [key, value] pairs for style resource pack.
 * @return a <tt>Map</tt>, containing all [key, value] pairs for styleresource pack.
 */
public Map<String,String> getStyleResources(){
  if (styleResources != null) {
    return styleResources;
  }
  try {
    ResourceBundle resourceBundle = ResourceBundle.getBundle(DEFAULT_STYLE_RESOURCE_PATH);
    Map<String,String> resources = new TreeMap<String,String>();
    this.initResources(resourceBundle, resources);
    this.initStylePluginResources(resources);
    styleResources = resources;
    return resources;
  } catch (RuntimeException e) {
    // Log the exception or wrap it in a custom exception
    throw new RuntimeException("Error initializing style resources", e);
  }
}
